-- =======================================================
-- 850導入 / DB install ─ 天M娃娃與卡片合成系統 (w_tm_combine)
-- =======================================================
SET NAMES utf8mb4;

DROP TABLE IF EXISTS `w_tm_combine`;
CREATE TABLE `w_tm_combine` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `npcid` int(11) NOT NULL DEFAULT 93064,
  `note` varchar(100) NOT NULL DEFAULT '',
  `action` varchar(50) NOT NULL DEFAULT '',
  `req_item_ids` varchar(255) NOT NULL COMMENT '合成材料候選清單 (逗號分隔)',
  `req_count` int(11) NOT NULL DEFAULT 4 COMMENT '所需材料總數量 (例如4合1)',
  `chance` int(11) NOT NULL DEFAULT 20 COMMENT '成功機率 (%)',
  `reward_item_id` varchar(100) NOT NULL COMMENT '成功產出道具ID',
  `msg_lack` varchar(100) NOT NULL DEFAULT '合成材料數量不足',
  `msg_fail` varchar(100) NOT NULL DEFAULT '合成失敗',
  `msg_success` varchar(100) NOT NULL DEFAULT '合成成功',
  `broadcast` varchar(255) NOT NULL DEFAULT '',
  `return_on_fail` tinyint(1) NOT NULL DEFAULT 1 COMMENT '失敗是否返還部分材料',
  `pity_record_id` int(11) NOT NULL DEFAULT 0 COMMENT '保底累計編號',
  `pity_count` int(11) NOT NULL DEFAULT 20 COMMENT '觸發必中保底次數',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='天M合成與保底系統';
